  <style>
    :root {
      color-scheme: light dark;
      --bg: #f4f7fb;
      --panel: rgba(255, 255, 255, 0.92);
      --text: #162033;
      --muted: #56637a;
      --border: rgba(22, 32, 51, 0.12);
      --accent: #5b6cff;
      --accent-strong: #4356ff;
