      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(91, 108, 255, 0.18), transparent 32%),
        radial-gradient(circle at top right, rgba(64, 196, 255, 0.14), transparent 24%),
        linear-gradient(180deg, #fbfcff 0%, var(--bg) 100%);
      line-height: 1.6;
